319	double GBDT::BoostFromAverage(int class_id, bool update_scorer) {
320	  Common::FunctionTimer fun_timer("GBDT::BoostFromAverage", global_timer);
321	  // boosting from average label; or customized "average" if implemented for the current objective
322	  if (models_.empty() && !train_score_updater_->has_init_score() && objective_function_ != nullptr) {
323	    if (config_->boost_from_average || (train_data_ != nullptr && train_data_->num_features() == 0)) {
324	      double init_score = ObtainAutomaticInitialScore(objective_function_, class_id);
325	      if (std::fabs(init_score) > kEpsilon) {
326	        if (update_scorer) {
327	          train_score_updater_->AddScore(init_score, class_id);
328	          for (auto& score_updater : valid_score_updater_) {
329	            score_updater->AddScore(init_score, class_id);
330	          }
331	        }
332	        Log::Info("Start training from score %lf", init_score);
333	        return init_score;
334	      }
335	    } else if (std::string(objective_function_->GetName()) == std::string("regression_l1")
336	               || std::string(objective_function_->GetName()) == std::string("quantile")
337	               || std::string(objective_function_->GetName()) == std::string("mape")) {
338	      Log::Warning("Disabling boost_from_average in %s may cause the slow convergence", objective_function_->GetName());
339	    }
340	  }
341	  return 0.0f;
342	}
