346	  std::vector<double> init_scores(num_tree_per_iteration_, 0.0);
347	  // boosting first
348	  if (gradients == nullptr || hessians == nullptr) {
349	    for (int cur_tree_id = 0; cur_tree_id < num_tree_per_iteration_; ++cur_tree_id) {
350	      init_scores[cur_tree_id] = BoostFromAverage(cur_tree_id, true);
351	    }
352	    Boosting();
353	    gradients = gradients_pointer_;
354	    hessians = hessians_pointer_;
355	  } else {
356	    // use customized objective function
