358	    CHECK(objective_function_ == nullptr);
359	    if (data_sample_strategy_->IsHessianChange()) {
360	      // need to copy customized gradients when using GOSS
361	      int64_t total_size = static_cast<int64_t>(num_data_) * num_tree_per_iteration_;
362	      #pragma omp parallel for num_threads(OMP_NUM_THREADS()) schedule(static)
363	      for (int64_t i = 0; i < total_size; ++i) {
364	        gradients_[i] = gradients[i];
365	        hessians_[i] = hessians[i];
366	      }
367	      CHECK_EQ(gradients_pointer_, gradients_.data());
368	      CHECK_EQ(hessians_pointer_, hessians_.data());
369	      gradients = gradients_pointer_;
370	      hessians = hessians_pointer_;
371	    }
372	  }
373	
374	  // bagging logic
375	  if (!config_->bagging_by_query) {
376	    data_sample_strategy_->Bagging(iter_, tree_learner_.get(), gradients_.data(), hessians_.data());
377	  }
378	  const bool is_use_subset = data_sample_strategy_->is_use_subset();
379	  const data_size_t bag_data_cnt = data_sample_strategy_->bag_data_cnt();
380	  const std::vector<data_size_t, Common::AlignmentAllocator<data_size_t, kAlignedSize>>& bag_data_indices = data_sample_strategy_->bag_data_indices();
381	
382	  if (objective_function_ == nullptr && is_use_subset && bag_data_cnt < num_data_ && !boosting_on_gpu_ && !data_sample_strategy_->IsHessianChange()) {
383	    ResetGradientBuffers();
384	  }
385	
386	  bool should_continue = false;
387	  for (int cur_tree_id = 0; cur_tree_id < num_tree_per_iteration_; ++cur_tree_id) {
388	    const size_t offset = static_cast<size_t>(cur_tree_id) * num_data_;
389	    std::unique_ptr<Tree> new_tree(new Tree(2, false, false));
390	    if (class_need_train_[cur_tree_id] && train_data_->num_features() > 0) {
391	      auto grad = gradients + offset;
392	      auto hess = hessians + offset;
393	      // need to copy gradients for bagging subset.
394	      if (is_use_subset && bag_data_cnt < num_data_ && !boosting_on_gpu_) {
395	        for (int i = 0; i < bag_data_cnt; ++i) {
396	          gradients_pointer_[offset + i] = grad[bag_data_indices[i]];
397	          hessians_pointer_[offset + i] = hess[bag_data_indices[i]];
398	        }
399	        grad = gradients_pointer_ + offset;
400	        hess = hessians_pointer_ + offset;
401	      }
402	      bool is_first_tree = models_.size() < static_cast<size_t>(num_tree_per_iteration_);
403	      new_tree.reset(tree_learner_->Train(grad, hess, is_first_tree));
404	    }
405	
406	    if (new_tree->num_leaves() > 1) {
407	      should_continue = true;
408	      auto score_ptr = train_score_updater_->score() + offset;
409	      auto residual_getter = [score_ptr](const label_t* label, int i) {return static_cast<double>(label[i]) - score_ptr[i]; };
