412	      // shrinkage by learning rate
413	      new_tree->Shrinkage(shrinkage_rate_);
414	      // update score
415	      UpdateScore(new_tree.get(), cur_tree_id);
416	      if (std::fabs(init_scores[cur_tree_id]) > kEpsilon) {
417	        new_tree->AddBias(init_scores[cur_tree_id]);
418	      }
419	    } else {
420	      // only add default score one-time
421	      if (models_.size() < static_cast<size_t>(num_tree_per_iteration_)) {
422	        if (objective_function_ != nullptr && !config_->boost_from_average && !train_score_updater_->has_init_score()) {
423	          init_scores[cur_tree_id] = ObtainAutomaticInitialScore(objective_function_, cur_tree_id);
424	          // updates scores
425	          train_score_updater_->AddScore(init_scores[cur_tree_id], cur_tree_id);
426	          for (auto& score_updater : valid_score_updater_) {
427	            score_updater->AddScore(init_scores[cur_tree_id], cur_tree_id);
428	          }
429	        }
430	        new_tree->AsConstantTree(init_scores[cur_tree_id], num_data_);
431	      } else {
432	        // extend init_scores with zeros
433	        new_tree->AsConstantTree(0, num_data_);
434	      }
435	    }
436	    // add model
437	    models_.push_back(std::move(new_tree));
438	  }
439	
440	  if (!should_continue) {
441	    Log::Warning("Stopped training because there are no more leaves that meet the split requirements");
442	    if (models_.size() > static_cast<size_t>(num_tree_per_iteration_)) {
443	      for (int cur_tree_id = 0; cur_tree_id < num_tree_per_iteration_; ++cur_tree_id) {
444	        models_.pop_back();
445	      }
446	    }
447	    return true;
448	  }
